from datetime import datetime
import pytz
import re
from faker import Faker


def task_func(epoch_milliseconds, seed=0, timezones=["UTC"]):
    fake = Faker()
    fake.seed_instance(seed)

    # Convert epoch milliseconds to an aware datetime in the current system timezone.
    utc_dt = datetime.fromtimestamp(epoch_milliseconds / 1000.0, tz=pytz.UTC)
    system_tz = datetime.now().astimezone().tzinfo
    local_dt = utc_dt.astimezone(system_tz)

    # Validate provided timezones.
    if timezones is None:
        timezones = []
    elif isinstance(timezones, str):
        timezones = [timezones]

    valid_timezones = []
    utc_offset_pattern = re.compile(r"^UTC([+-])(\d{1,2}):([0-5]\d)$")

    for tz_name in timezones:
        if not isinstance(tz_name, str):
            continue
        if tz_name in pytz.all_timezones:
            valid_timezones.append(tz_name)
            continue
        match = utc_offset_pattern.fullmatch(tz_name)
        if match:
            sign, hours_str, minutes_str = match.groups()
            hours = int(hours_str)
            minutes = int(minutes_str)
            if hours <= 23:
                valid_timezones.append(tz_name)

    # Select timezone: UTC if none valid, otherwise choose one valid timezone at random.
    if not valid_timezones:
        selected_timezone = "UTC"
    else:
        selected_timezone = fake.random_element(elements=valid_timezones)

    # Build a tzinfo object for conversion.
    if selected_timezone == "UTC":
        target_tzinfo = pytz.UTC
    elif selected_timezone in pytz.all_timezones:
        target_tzinfo = pytz.timezone(selected_timezone)
    else:
        match = utc_offset_pattern.fullmatch(selected_timezone)
        if match:
            sign, hours_str, minutes_str = match.groups()
            offset_minutes = int(hours_str) * 60 + int(minutes_str)
            if sign == "-":
                offset_minutes = -offset_minutes
            target_tzinfo = pytz.FixedOffset(offset_minutes)
        else:
            target_tzinfo = pytz.UTC
            selected_timezone = "UTC"

    event_dt = local_dt.astimezone(target_tzinfo)

    event_name = fake.catch_phrase()

    schedule = {
        "date": event_dt.date().isoformat(),
        "time": event_dt.strftime("%H:%M:%S"),
        "timezone": selected_timezone,
    }

    return {event_name: [schedule]}
